-- product_cards
insert into advisor_structured_product_cards (
  client_id, sku, canonical_name, short_name, what_it_is, who_asks_about_it, common_use_cases,
  how_to_use_short, what_to_expect_soft, contraindications_short, primary_image_url
) values
('whieda', 'EU-N000024-24', 'Набор прибора Вэнтун 1.0', 'Вэнтун 1.0', 'Вэнтун — это ваша домашняя станция глубокого теплового восстановления через стопы и поясницу. Его чаще всего выбирают на вечер, когда ноги гудят, тело знобит, спину ломит от сидячей работы, а энергии уже не осталось.', 'Для людей с сидячей или стоячей работой: офис, торговля, бьюти-сфера, дорога. Для тех, кто постоянно мерзнет, страдает от отеков ног и мечтает о полноценном глубоком прогреве тела без выхода из дома.', 'ноги гудят и горят после тяжелого дня на ногах; мерзнут конечности и постоянно холодные руки или ноги; крутит суставы на погоду; хочется глубоко расслабиться и быстрее уснуть', 'Вы садитесь в кресло или на стул, ставите босые стопы на платформу, а тепловой пояс фиксируете на пояснице. Включаете прибор по инструкции и отдыхаете 20-30 минут в спокойном пассивном режиме.', 'Вэнтун воспринимается как глубокий вечерний ритуал восстановления. Он дает ощущение, будто тело заново отогрелось и разгрузилось: уходят тяжесть, застой и внутреннее напряжение после тяжелого дня.', 'кардиостимулятор; беременность; высокая температура тела; острые воспалительные процессы; металлические импланты в ногах или позвоночнике', 'https://mlm.sysarch.pro/whieda-media/wentong.jpg'),
('whieda', 'M015-00', 'Активатор клеток', 'Активатор клеток', 'Активатор клеток — это ваш универсальный домашний спасатель для локальной работы с зонами дискомфорта: зажатая шея, ноющая спина, колени, мышцы, связки и точки хронического напряжения. Его берут как самый понятный первый прибор по принципу: достал из коробки, включил и мягко поработал с местом, которое беспокоит.', 'Для людей, которые устали жить на мазях, таблетках и временных пластырях. Для тех, кто хочет иметь под рукой понятный инструмент быстрой помощи телу дома, на даче или после нагрузки без долгой подготовки.', 'заклинило шею после рабочего дня за компьютером; спина стала деревянной после сидения в машине или работы на грядках; ноет колено на погоду или после физической нагрузки; потянули связку или мышцу на тренировке; синяки, отеки и мелкие повреждения кожи проходят слишком медленно', 'Плавно обдувайте прибором проблемную зону теплым воздухом по инструкции, сохраняя комфортное расстояние до кожи. Используется локально, избегая прямого воздействия на открытые глаза и зоны с острыми повреждениями кожи.', 'В отличие от разогревающих мазей, которые дают только короткий внешний эффект, прибор воспринимается как полноценный домашний инструмент регулярной локальной процедуры. Базовая версия лаконична, надежна и полностью закрывает задачу первого универсального прибора.', 'беременность; онкологические заболевания; наличие кардиостимулятора или стентов в зоне воздействия; высокая температура тела; активный герпес с лопнувшими пузырьками; открытые раны; тяжелые острые состояния', 'https://mlm.sysarch.pro/whieda-media/aktivator-kletok.jpg'),
('whieda', 'EU-N000031-25', 'Активатор клеток PRO (комплект)', 'Активатор клеток PRO', 'Активатор клеток PRO — это старшая версия клеточного активатора в стильном защитном кейсе. Это выбор для тех, кто хочет максимум удобства для семьи, поездок, выездных презентаций или регулярной работы с клиентами.', 'Для партнеров, которые строят бизнес и хотят производить сильное впечатление на презентациях. Для продвинутых пользователей, ценящих премиальный дизайн, точечные настройки и максимальную защиту устройства.', 'нужен солидный подарок для близких; часто путешествуете и нужен прочный кейс для перевозки; хочется раздельно регулировать силу обдува и температуру прогрева; нужен прибор, который визуально выглядит дорого и презентабельно', 'Используется как базовый активатор, но с расширенными возможностями: можно точнее настроить режим под человека, заблокировать кнопки от случайного нажатия и применять сменные насадки для более точечной работы. Насадки требуют аккуратного обращения.', 'PRO не про магию, а про уровень комфорта и удобства. Защитная фильтр-сетка, автопродувка, кейс, более гибкие настройки и премиальный внешний вид делают его сильнее как семейный и как презентационный прибор.', 'беременность; онкология; кардиостимулятор; стенты; высокая температура; открытые повреждения кожи; герпес в активной фазе; воздействие непосредственно на глаза', 'https://mlm.sysarch.pro/whieda-media/aktivator-kletok-pro.jpg'),
('whieda', 'D014', 'Высокотехнологичные компьютерные очки', 'Компьютерные очки', 'Компьютерные очки WHIEDA — это ваш ежедневный барьер защиты глаз от света мониторов, смартфонов и офисных ламп. Простой аксессуар, который помогает не доводить день до сухости, рези и тяжелой головы к вечеру.', 'Для программистов, офисных сотрудников, студентов, геймеров, активных пользователей соцсетей и водителей, которые часто ездят вечером и ночью.', 'за экраном больше 4-6 часов в день; к вечеру белки глаз краснеют и сохнут; ощущение песка в глазах после работы; тяжесть и тупая боль в области лба; встречные фары ночью сильно слепят', 'Просто надевайте очки при работе с цифровыми экранами. Они не требуют сложного ухода и не искажают привычную цветопередачу в повседневной работе.', 'Их ценят не за желтые стекла, а за ощущение более спокойных глаз к вечеру. Рабочий ритм остается тем же, но глаза меньше устают, а голова ощущается легче.', 'не являются лечебным средством при тяжелых офтальмологических заболеваниях; при резком падении зрения; сильной глазной боли; травмах; гнойных процессах нужна отдельная проверка', 'https://mlm.sysarch.pro/whieda-media/computer-glasses-1.jpg'),
('whieda', 'D013', 'Стельки с анионами', 'Стельки с анионами', 'Анионовые стельки — это ваш незаметный личный помощник внутри обуви для поддержки стоп, более мягкой ходьбы и меньшей усталости к вечеру. Вы просто живете обычный день, а стопы получают поддержку при каждом шаге.', 'Для продавцов, курьеров, парикмахеров, спортсменов, любителей пеших прогулок и всех, у кого к вечеру горят стопы и ноет поясница от ходьбы.', 'ноги гудят и отекают к вечеру; тяжесть и тупая боль в пояснице после рабочего дня; обычная обувь быстро стаптывается; хочется снизить ударную нагрузку на колени и позвоночник', 'Вложите стельки в повседневную, спортивную или рабочую обувь, при необходимости подрежьте под размер по контурным линиям на обороте. Подходят для ежедневного использования.', 'В отличие от мягких стелек масс-маркета, здесь ценят сочетание формы, ощущения опоры и ежедневного комфорта в ногах. Это не волшебство, а очень практичная вещь, которую замечаешь именно к концу длинного дня.', 'открытые раны на стопах; мокнущие язвы; выраженные аллергические реакции кожи; тяжелая диабетическая стопа', 'https://mlm.sysarch.pro/whieda-media/anion-insoles.jpg'),
('whieda', 'T015', 'Палантин', 'Энергетический палантин', 'Энергетический палантин — это ваш мягкий и стильный бронежилет от сквозняков, кондиционеров и мышечного напряжения в шее и плечах. Не мазь и не пластырь, а элегантный аксессуар, который можно носить в офисе, машине, самолете или дома.', 'Для офисных сотрудников под кондиционерами, путешественников, людей с сидячей работой и всех, у кого к вечеру шея становится каменной и не хочет поворачиваться.', 'шею и плечи регулярно продувает в машине или офисе; воротниковая зона зажата и гудит после компьютера; хочется мягкого тепла в поездке или перелете; нужен стильный аксессуар с реальной пользой для тела', 'Носите его как шарф, накидку или палантин, укутывая зону шеи, плеч или поясницы по мере необходимости в течение дня или во время сна.', 'Его любят за сочетание пользы и внешнего вида: можно выглядеть нормально и при этом получать деликатное тепло и ощущение расслабления в зоне шеи и плеч без жжения, запахов и следов на коже.', 'высокая температура тела; острые травмы позвоночника; сильная непрекращающаяся боль требует отдельной проверки', 'https://mlm.sysarch.pro/whieda-media/palantin-1.jpg'),
('whieda', 'EU-N000021-24', 'Набор Массажёра Magic Foherb 3.0 (TUV)', 'Magic FoHerb 3.0', 'Magic FoHerb 3.0 — это домашний SPA-комбайн и рабочий аппаратный комплекс для мастера. Его ценят за глубокую проработку зажатых мышц, лимфодренажное воздействие и возможность получать мощный результат без физического износа рук.', 'Для массажистов, мануальных и бьюти-мастеров, которые хотят добавить дорогую аппаратную услугу в работу. И для семей, которые хотят иметь дома серьезный физиотерапевтический прибор премиум-класса.', 'спина зажата колом; шея не поворачивается; глубокие застойные отеки тела и конечностей; усталость рук мастера при плотном потоке клиентов; нужно быстро и глубоко расслабить мышцы после перегрузки', 'Перед сеансом прибор полностью заряжают. Работа идет в специальных токопроводящих перчатках поверх сухих резиновых. Контакт с телом начинают плавно. Основные зоны — спина, руки и ноги; лицо и шея только на минимальной мощности после обучения.', 'Главная фишка — глубина проработки без ощущения грубой силовой работы. Клиент чувствует плотное, глубокое воздействие, а мастер экономит руки и может работать дольше и стабильнее.', 'беременность; кардиостимулятор; инсулиновая помпа; металлические импланты в зоне воздействия; эпилепсия; онкология; острые состояния', 'https://mlm.sysarch.pro/whieda-media/magic-foherb.jpg'),
('whieda', 'M014-00', 'МИНИСАУНА "БА-ГУА"', 'Минисауна БА-ГУА', 'Минисауна Ба-Гуа — это ваш личный SPA-салон дома для мягкого глубокого прогрева и полной перезагрузки после тяжелого дня. Ее выбирают те, кто хочет хорошо пропотеть и снять напряжение, но не любит душные общественные бани.', 'Для женщин и мужчин, которые заботятся о коже, фигуре и восстановлении. Для жителей города, живущих в стрессе и дефиците времени, которым нужен личный ритуал расслабления без поездок в SPA.', 'хочется глубоко прогреться после холода; ощущение тяжести, забитости мышц и застоя жидкости в теле; тяжело переносится обычная баня; нужен личный ритуал расслабления и тишины', 'Кабина собирается за пару минут. Внутрь ставят табурет, заходят, застегивают молнию и садятся, оставляя голову снаружи. До процедуры лучше выпить теплой воды. Рекомендуемое время сеанса — 30-40 минут.', 'Ба-Гуа любят за ощущение мягкой, глубокой бани без удушливого пара. Тело хорошо прогревается, а голова остается снаружи, поэтому процедура переносится заметно комфортнее, чем обычная парилка.', 'беременность; кардиостимулятор; онкология; тяжелая сердечная недостаточность; острые воспалительные процессы; высокая температура тела; выраженные проблемы с давлением', 'https://mlm.sysarch.pro/whieda-media/bagua.jpg'),
('whieda', 'F028-00', 'Капсулы Линчжи Фохоу', 'Линчжи', 'Капсулы Линчжи — грибной продукт для тех, кто просыпается без ресурса, тяжело отключает голову вечером и хочет мягкую поддержку нервной системы и иммунитета.', 'Люди с перегрузом, плохим сном, тревожностью, частыми простудами и ощущением, что голова не отдыхает даже ночью.', 'плохо засыпаете; поверхностный сон; часто простываете; голова шумит от перегруза; нужен мягкий вечерний продукт', 'Принимать ежедневно по инструкции. Часто выбирают на вечер, потому что продукт связывают с более спокойным сном и восстановлением.', 'Смысл не в резком стимуле, а в мягком накопительном ощущении: меньше внутренней суеты, легче отключиться и восстановиться.', 'индивидуальная непереносимость; аллергическая реакция на компоненты', 'https://mlm.sysarch.pro/whieda-media/lingzhi.jpg'),
('whieda', 'F031-00', 'Чай Лювэй', 'Чай Лювэй', 'Чай Лювэй — фиточай на основе пуэра и трав для тех, кто хочет не просто чай, а более функциональный дневной напиток для легкости и тонуса.', 'Люди, которым тяжело после еды, хочется меньше отекать, нужен мягкий дневной тонус и понятный ритуал на каждый день.', 'тяжесть после еды; хочется больше легкости; нужен мягкий дневной тонус; хочется заменить обычный чай на более функциональный напиток; к вечеру отекаете', 'Заваривать по инструкции и пить до 18:00. Не превращать его в ночной тонизирующий напиток.', 'Обычно его ценят за ощущение легкости, более собранное состояние днем и приятный ритуал, который легко встроить в каждый день.', 'индивидуальная непереносимость; чувствительность к тонизирующим напиткам; поздний вечер при склонности к бессоннице', 'https://mlm.sysarch.pro/whieda-media/liuwei-tea.jpg'),
('whieda', 'F038-00', 'Низкомолекулярный соевый пептид', 'Соевый пептид', 'Низкомолекулярный соевый пептид — легкоусвояемый белковый продукт, когда нужен не спортпит ради качалки, а понятное восстановление, сытость и поддержка ресурса.', 'Люди 40+, после болезней, при усталости, снижении белка в рационе, тренировках или желании поддержать мышцы без тяжести для ЖКТ.', 'слабость после болезни; устаете к вечеру; не добираете белок; восстанавливаетесь после нагрузок; нужен мягкий продукт для мышц и тонуса', 'Разводить в воде по инструкции. Обычно берут как повседневную белковую поддержку, а не как разовый энергетик.', 'Его любят за ощущение сытости, более ровную энергию и то, что он воспринимается легче обычного белка.', 'индивидуальная непереносимость сои; дети 3-10 лет только с осторожностью; тяжелые заболевания пищеварительной системы; тяжелые эндокринные состояния', 'https://mlm.sysarch.pro/whieda-media/soy-peptide.jpg'),
('whieda', 'F001-02', 'Эликсир Фохоу', 'Фохоу', 'Эликсир Фохоу — жидкий продукт базовой регуляции для тех, кто чувствует, что организму не хватает ресурса, устойчивости и внутреннего восстановления.', 'Люди после перегрузок, частых простуд, снижения тонуса, долгого восстановления и ощущения, что сил стало меньше, чем раньше.', 'часто нет сил; долго восстанавливаетесь; хочется базовую поддержку; часто простываете; нужен понятный стартовый продукт', 'Принимать по инструкции. Обычно его рассматривают как базовый продукт на регулярной основе, а не как разовую таблетку на экстренный случай.', 'Его ценят за ощущение более ровного ресурса и за то, что он воспринимается как базовая ежедневная поддержка, а не сложная схема.', 'Индивидуальная непереносимость компонентов; детям начинать только с малых доз по инструкции', 'https://mlm.sysarch.pro/whieda-media/elixir-fohou.jpg'),
('whieda', 'F002-02', 'Эликсир 3 Драгоценности', '3 Драгоценности', 'Эликсир 3 Драгоценности — более тонизирующий эликсир для тех, кому нужен не просто фон, а ощущение подпитки после серьезной усталости и перегрузки.', 'Люди после тяжелых нагрузок, затяжного восстановления, возрастного спада энергии и все, кому хочется чувствовать больше внутреннего тонуса.', 'хроническая усталость; долго восстанавливаетесь; нужен взрослый тонизирующий продукт; хочется больше ресурса; возрастной спад энергии', 'Принимать по инструкции и не ставить первым продуктом в хаотичном режиме. Важное ограничение по возрасту сохранять всегда.', 'Обычно его выбирают, когда хочется более выраженного ощущения подпитки и жизненного тонуса, чем от базовых продуктов.', 'Беременность; кормление грудью; мальчики до 14 лет; девочки до 16 лет; индивидуальная непереносимость', 'https://mlm.sysarch.pro/whieda-media/elixir-3-treasures.jpg'),
('whieda', 'F003-02', 'Эликсир Саньцин', 'Саньцин', 'Эликсир Саньцин — продукт очищающего и восстановительного профиля, когда хочется больше легкости по ЖКТ и ощущения, что организм разгружается.', 'Люди, у которых тяжесть, перегрузка по питанию, склонность к аллергическим реакциям и ощущение, что тело просит мягкого очищения.', 'тяжесть и перегрузка по ЖКТ; хочется мягкого очищения; нужен продукт в детокс-логике; ощущение интоксикации; хочется больше легкости', 'Принимать по инструкции курсом. Это не напиток на настроение, а продукт, который обычно берут в системный очищающий этап.', 'Обычно его выбирают, когда нужен не просто комфорт на один день, а ощущение более глубокой разгрузки и восстановления слизистой ЖКТ.', 'Беременность; кормление грудью; склонность к кровотечениям; менструация; ранний период после серьезных операций; индивидуальная непереносимость', 'https://mlm.sysarch.pro/whieda-media/elixir-sanqing.jpg'),
('whieda', 'F011-02', 'Роза Фохоу', 'Роза Фохоу', 'Роза Фохоу — пребиотическая паста для тех, у кого кишечник живет своей жизнью: то тяжесть, то редкий стул, то ощущение, что питание явно не радует микрофлору.', 'Люди с запорами, тяжестью после еды, нестабильным стулом и желанием поддержать кишечник мягко, без жестких схем.', 'редкий стул; тяжесть после еды; хочется мягче ходить в туалет; нужен повседневный продукт для кишечника; хочется поддержать микрофлору', 'Принимать ежедневно по инструкции. Обычно ее встраивают как спокойный бытовой продукт, а не как экстренную меру на один день.', 'Ее любят за простой формат: вкусная паста, понятный ритуал и ощущение, что кишечник работает спокойнее и ровнее.', 'Индивидуальная непереносимость компонентов', 'https://mlm.sysarch.pro/whieda-media/rose-fohou.jpg'),
('whieda', 'F024-00', 'Капсулы Сюэчинфу', 'Сюэчинфу', 'Сюэчинфу — продукт сосудистого профиля, который обычно смотрят, когда говорят про густую кровь, тяжесть, давление и желание поддержать сосуды глубже, чем просто чаем.', 'Люди 40+, при тяжести в ногах, сосудистых вопросах, скачках давления и разговорах про очищение сосудов и текучесть крови.', 'тяжесть в ногах; разговор про сосуды; густая кровь; хочется поддержать давление; нужен сосудистый продукт в системе детокса', 'Принимать строго по инструкции и не стартовать хаотично. Важно помнить, что это не первый продукт в системе и у него есть чувствительные ограничения.', 'Обычно его ценят за ощущение системной сосудистой поддержки, но смысл здесь именно в аккуратности, а не в резком самолечении.', 'Активные кровотечения; менструация; восстановительный период после операций; индивидуальная непереносимость', 'https://mlm.sysarch.pro/whieda-media/xueqingfu.jpg'),
('whieda', 'D003-00', 'Анионовые прокладки', 'Анионовые прокладки', 'Анионовые прокладки WHIEDA — это гигиенический продукт для тех, кто хочет больше комфорта, сухости и ощущения чистоты, чем от обычных магазинных прокладок.', 'Женщины, которым важны комфорт, отсутствие запаха, мягкость в критические дни и более приятное ежедневное использование.', 'не нравятся обычные прокладки; хочется меньше запаха; важен комфорт в критические дни; ищете более приятные ежедневки; чувствительная кожа', 'Использовать как обычные прокладки по необходимости. Для простого ответа этого достаточно, без самодельных лечебных сценариев.', 'Их ценят за сухость, комфорт и ощущение, что пользоваться ими просто приятнее, чем обычными вариантами из масс-маркета.', 'Индивидуальная непереносимость компонентов; выраженное раздражение кожи', 'https://mlm.sysarch.pro/whieda-media/anion-pads-mix.png'),
('whieda', 'F036-00', 'Спирулина', 'Спирулина', 'Спирулина — базовый продукт для тех, кто хочет поддержать питание, ресурс и ощущение, что организму есть из чего восстанавливаться.', 'Люди с усталостью, снижением тонуса, дефицитным питанием и желанием добавить в рацион более плотный по составу ежедневный продукт.', 'устаете; хотите более питательный продукт; нужен базовый повседневный БАД; хочется поддержать ресурс и восстановление', 'Принимать по инструкции как повседневный продукт. Это не экстренный стимулятор, а накопительная пищевая поддержка.', 'Обычно ее выбирают за ощущение более ровного фона и как понятную ежедневную добавку без сложной схемы.', 'Индивидуальная непереносимость компонентов', NULL),
('whieda', 'F007-00', 'Капсулы Железо, Кальций, Цинк, Селен', 'Железо, Кальций, Цинк, Селен', 'Комплекс Железо, Кальций, Цинк, Селен — вариант для тех, кто не хочет собирать микроэлементы по банкам и ищет базовую поддержку по дефицитам в одном продукте.', 'Люди, которые думают про кости, зубы, ногти, железо, иммунитет и хотят простой комплекс без россыпи отдельных банок.', 'хочется комплекс микроэлементов; думаете про кости и зубы; слабые ногти; нужен повседневный минеральный продукт; не хотите покупать все по отдельности', 'Принимать по инструкции курсом. Смысл в регулярности, а не в разовом приеме от усталости.', 'Обычно его ценят за простоту: один комплекс вместо нескольких отдельных банок и понятный бытовой формат.', 'Индивидуальная непереносимость; осторожность при уже известном избытке микроэлементов', 'https://mlm.sysarch.pro/whieda-media/zinc-iron-calcium-selenium.jpg'),
('whieda', 'F034-00', 'Кофейный напиток с кордицепсом и коллагеном', 'Кофе с кордицепсом', 'Кофе с кордицепсом и коллагеном — напиток для тех, кто любит кофе, но хочет более мягкий и функциональный вариант с дополнительной пользой по ощущениям.', 'Люди, которым нравится кофе, нужен утренний ритуал и хочется не просто взбодриться, а получить более ровный старт дня.', 'любите кофе; нужен более мягкий вариант; хочется утренний ритуал; нужен напиток с ощущением пользы; не хочется просто сладкий 3-в-1', 'Заваривать по инструкции и пить как утренний или дневной напиток. Не использовать как оправдание пить его бесконтрольно весь день.', 'Обычно его любят за вкус, более мягкое ощущение по сравнению с обычным кофе и ощущение функционального напитка, а не просто стимулятора.', 'Индивидуальная непереносимость компонентов; чувствительность к кофеину', NULL),
('whieda', 'F071-00', 'Паста Цинфэн', 'Цинфэн', 'Цинфэн — паста для тех, кто хочет мягкий вечерний продукт в сторону сосудов, давления, отеков и общего ощущения тяжести в теле.', 'Люди, которые думают про давление, отеки, сосудистую поддержку и ищут бытовой продукт, который удобно вписать в день.', 'склонность к отекам; хочется мягкую сосудистую поддержку; думаете про давление; нужен вечерний продукт; хочется меньше тяжести', 'Принимать по инструкции. Обычно его воспринимают как спокойный регулярный продукт, а не как замену таблеткам от давления.', 'Его выбирают за мягкий формат и ощущение повседневной поддержки, когда не хочется сложных схем.', 'Индивидуальная непереносимость компонентов', NULL),
('whieda', 'D017-00', 'Водородный стержень', 'Водородный стержень', 'Водородный стержень — аксессуар для воды, который обычно берут те, кому нравится идея пить более функциональную воду каждый день.', 'Люди, которые следят за качеством воды, любят бытовые wellness-ритуалы и хотят простой ежедневный продукт без сложного применения.', 'хочется улучшить воду; нужен ежедневный wellness-ритуал; любите простые бытовые решения; ищете полезный аксессуар для воды', 'Использовать по инструкции для подготовки воды. Для простого ответа достаточно этого, без лишней псевдонауки.', 'Обычно его ценят за простоту: добавил в рутину воду и получил еще один аккуратный ежедневный шаг в сторону заботы о себе.', 'Индивидуальная чувствительность; вопросы по конкретным заболеваниям и лечебным схемам требуют отдельной проверки', NULL),
('whieda', 'D011-00', 'Гель очищающий Foherb', 'Очищающий гель Foherb', 'Очищающий гель Foherb — продукт интимной гигиены для тех, кто хочет более деликатный и адресный уход, чем обычные средства масс-маркета.', 'Женщины, которым важны комфорт, деликатный уход, ощущение чистоты и аккуратная поддержка микрофлоры без жестких средств.', 'деликатный интимный уход; дискомфорт от обычных средств; хочется более мягкий продукт; нужен аккуратный уход курсом', 'Использовать по инструкции. Это гигиенический продукт, а не поле для домашних лечебных экспериментов.', 'Его выбирают за ощущение мягкости и более деликатного ухода там, где обычные средства могут не нравиться по ощущениям.', 'Менструация; беременность; аллергическая реакция на компоненты', NULL)
