-- business_faq
insert into advisor_structured_business_faq (client_id, faq_id, title, answer_text, aliases, priority, active) values
('whieda', 'BUS-FAQ-01', 'PV - это деньги?', 'PV - это объём или баллы маркетинг-плана. Цена товара и PV могут быть связаны, но это не одно и то же. Точные PV по товару лучше смотреть в актуальном прайсе.', 'что такое pv | pv это деньги | pv деньги | баллы это деньги | что значат pv', 100, true),
('whieda', 'BUS-FAQ-02', 'Кэшбэк можно вывести?', 'В материалах WHIEDA кэшбэк первой покупки описан как внутренний ресурс для части повторных покупок, а не как наличные на вывод. Конкретные условия и цифры нужно сверять по действующему плану.', 'кэшбэк вывести | кешбек вывести | кэшбек это деньги | можно снять кэшбэк', 100, true),
('whieda', 'BUS-FAQ-03', 'Что такое повторная покупка?', 'Повторная покупка - отдельный сценарий после регистрации. В маркетинг-плане она связана с товарооборотом и действующими условиями кабинета. По конкретному товару цену и доступные условия нужно смотреть в актуальном прайсе.', 'что такое повторная покупка | повторка это что | как работает повторка | повторные покупки', 100, true),
('whieda', 'BUS-FAQ-04', 'Степ гарантирован?', 'Степ возникает только при выполнении условий пары и считается по действующему маркетинг-плану. Его нельзя обещать заранее или называть гарантированным доходом.', 'степ гарантирован | что такое степ | когда будет степ | степ бонус', 100, true),
('whieda', 'BUS-FAQ-05', 'Что такое бинарный бонус?', 'По внутреннему материалу бинарный бонус относится к обороту меньшей ветки, который не был учтён степом. Точные условия и расчёт зависят от действующего маркетинг-плана.', 'что такое бинарный бонус | бинар это что | как работает бинар', 100, true),
('whieda', 'BUS-FAQ-06', 'Что выгоднее: розница или регистрация?', 'Это разные задачи: розница подходит для знакомства с товаром, а регистрация связана с кабинетом, маркетинг-планом и повторными покупками. Сравнивать лучше по цели человека, текущей цене товара и действующим условиям.', 'что выгоднее розница или регистрация | розница или регистрация | первичка или розница | регистрироваться или купить', 100, true),
('whieda', 'BUS-FAQ-07', 'Как работают повторные покупки?', 'Повторные покупки - отдельная часть маркетинг-плана после регистрации. Условия и глубина зависят от статуса и актуальных правил компании.', 'как работают повторные покупки|повторные покупки как работают|повторка как работает', 100, true),
('whieda', 'BUS-FAQ-08', 'Степ гарантирован?', 'Степ возникает только при выполнении условий пары и считается по действующему маркетинг-плану. Заранее обещать его нельзя.', 'степ гарантирован|гарантирован ли степ|когда будет степ', 100, true),
('whieda', 'BUS-FAQ-09', 'Что такое бинарный бонус?', 'Бинарный бонус в материалах связан с оборотом меньшей ветки, который не был учтен степом. Точный расчет зависит от действующего маркетинг-плана.', 'что такое бинарный бонус|бинар это что|как работает бинар', 100, true),
('whieda', 'BUS-FAQ-10', 'Можно посчитать доход?', 'Можно разобрать механику и сценарии по текущему плану. Доход заранее обещать нельзя: он зависит от объема структуры, активности и правил компании.', 'можно посчитать доход|сколько я заработаю|какой будет доход', 100, true),
('whieda', 'BUS-FAQ-11', 'Когда происходят выплаты?', 'Сроки и порядок начислений нужно сверять по действующему маркетинг-плану. Бинар, дерево и статусные бонусы имеют свои условия и расписание компании.', 'когда выплаты|когда начисляют бонусы|срок выплат', 100, true),
('whieda', 'BUS-FAQ-12', 'Что такое золотой треугольник?', 'В материалах это схема построения трех веток. Ее рассматривают как логику баланса структуры и выполнения квалификаций, а не как гарантию результата.', 'что такое золотой треугольник|золотой треугольник', 100, true),
('whieda', 'BUS-FAQ-13', 'Как работают статусы?', 'Статусы связаны с объемом веток, пакетами и актуальными условиями маркетинг-плана. Могу объяснить механику, а точный расчет нужно делать по текущим правилам.', 'как работают статусы|карьерные статусы|директор амбассадор', 100, true)
on conflict (client_id, faq_id) do update set title=excluded.title, answer_text=excluded.answer_text, aliases=excluded.aliases, priority=excluded.priority, active=true;

-- business_objections
insert into advisor_structured_business_objections (client_id, objection_id, title, aliases, first_reply, clarify, next_step, do_not_say, priority, active) values
('whieda', 'OBJ-01', 'Нет денег / дорого', 'нет денег | дорого | не потяну | сейчас нет бюджета | не могу себе позволить', 'Понимаю. Скажи честно: вопрос именно в сумме сейчас, или пока не видно, за что эта сумма?', 'Бюджет, ценность продукта, недоверие к бизнесу или нежелание принимать решение сейчас.', 'Показать актуальную цену/варианты и дать время подумать без давления.', 'Не стыдить за деньги и не говорить «ты заработаешь и отобьёшь».', 100, true),
('whieda', 'OBJ-02', 'Нет времени', 'нет времени | очень занят | некогда | работа и семья', 'Понимаю, времени у всех мало. Что именно сейчас не помещается: коротко посмотреть материал, пользоваться продуктом или разбираться в партнёрстве?', 'Знакомство, использование продукта или ведение бизнеса.', 'Предложить короткий материал или согласовать удобное время для 10-15 минут разговора.', 'Не спорить «у всех 24 часа» и не обесценивать нагрузку человека.', 100, true),
('whieda', 'OBJ-03', 'Это Китай / на маркетплейсе дешевле', 'это китай | алиэкспресс | али | дешевле | копия | подделка | почему так дорого', 'Нормальный вопрос. Что для тебя здесь главное: происхождение, качество, гарантия, комплектация или именно сравнение цены?', 'Скепсис к стране производства или сравнение конкретного товара и комплектации.', 'Дать утверждённый обзор, инструкцию, фото комплектации или сравнение, если оно есть в SQL.', 'Не говорить, что любой товар на маркетплейсе - подделка, и не обещать лечебное качество.', 100, true),
('whieda', 'OBJ-04', 'Это МЛМ / пирамида', 'это млм | сетевой | пирамида | сетевуха | развод | лохотрон', 'Понимаю, у многих был неприятный опыт. Что именно вызывает вопрос: продукт, правила выплат, регистрация или опыт прошлой компании?', 'Конкретная причина, а не общий ярлык.', 'Предложить разобрать один конкретный пункт или показать действующий маркетинг-план.', 'Не спорить, не обещать «здесь точно не так», не скрывать название компании.', 100, true),
('whieda', 'OBJ-05', 'Сначала посмотрю на тебя / сколько ты заработал', 'посмотрю на тебя | сколько ты заработал | покажи доход | сначала докажи | какие у тебя результаты', 'Справедливый вопрос. Я могу честно рассказать о своём текущем опыте, но решение лучше принимать по продукту, условиям и тому, подходит ли это лично тебе.', 'Доказательства, личный пример или проверка уровня риска.', 'Дать честный личный ответ в рамках фактов, затем предложить проверить официальные условия и материалы.', 'Не соревноваться доходами и не говорить «смотри на лидеров, а не на меня».', 100, true),
('whieda', 'OBJ-06', 'Я подумаю', 'я подумаю | надо подумать | потом решу | не сейчас | давай позже', 'Конечно. Чтобы не грузить тебя лишним, скажи: над чем именно хочешь подумать - продукт, цена, формат партнёрства или что-то ещё?', 'Один реальный стоп-фактор: нормальная пауза или недосказанное сомнение.', 'Согласовать спокойный follow-up: какой материал прислать и когда удобно вернуться к разговору.', 'Не требовать решения сейчас и не трактовать паузу как согласие.', 100, true)
on conflict (client_id, objection_id) do update set title=excluded.title, aliases=excluded.aliases, first_reply=excluded.first_reply, clarify=excluded.clarify, next_step=excluded.next_step, do_not_say=excluded.do_not_say, priority=excluded.priority, active=true;

-- capability_responses
insert into advisor_structured_capability_responses (client_id, response_id, intent_id, answer_text, enabled) values
('whieda', 'service-greeting', 'greeting', 'Привет! Я советник WHIEDA. Могу быстро показать товар с фото, ценой и видео, сравнить приборы, ответить по PV, повторке и старту. Напишите, например: «активатор», «цена Вэнтуна» или «сравни Активатор и PRO».', true),
('whieda', 'service-smalltalk', 'smalltalk_status', 'На связи. Могу помочь с товарами WHIEDA, ценой, фото или видео, сравнением и бизнес-вопросами. С чего начнём?', true),
('whieda', 'service-capabilities', 'capabilities', 'Я могу помочь с WHIEDA:⏎⏎📦 Товары⏎• рассказать о товаре простыми словами;⏎• показать фото;⏎• сравнить товары;⏎• подсказать, что посмотреть под вашу задачу.⏎⏎💳 Цены и корзина⏎• дать цену, PV, первичную и повторную покупку;⏎• посчитать несколько товаров вместе;⏎• подсказать актуальные акции и выгодный старт.⏎⏎🧮 Калькулятор товаров. Напишите:⏎Посчитай: Активатор клеток, БЭМ, Ба-Гуа⏎⏎🎥 Материалы⏎• отправить видео, презентацию, инструкцию или сертификат, если они есть в базе.⏎⏎📈 Бизнес⏎• объяснить повторные покупки, PV, бинар, Step и статусы;⏎• разобрать варианты старта и маркетинг-план;⏎• подсказать ближайшую встречу или мероприятие.⏎⏎Напишите название товара или вопрос своими словами.', true),
('whieda', 'service-help', 'help', 'Напишите, что нужно: товар, цена, фото, видео, сравнение или бизнес-вопрос.  Примеры: «активатор», «цена Ба-Гуа», «дай видео Вэнтуна», «чем PRO отличается от обычного», «что такое повторка».', true)
on conflict (client_id, response_id) do update set intent_id=excluded.intent_id, answer_text=excluded.answer_text, enabled=true;

-- clarification_prompts
insert into advisor_structured_clarification_prompts (client_id, clarification_key, prompt_text, enabled) values
('whieda', 'product_ambiguity_activator', 'Вы про Активатор клеток или Активатор клеток PRO?', true),
('whieda', 'product_known_task_unknown', 'Активатор клеток знаю. Что показать: кратко о приборе, применение, цену, отличия PRO, фото или видео?', true),
('whieda', 'price_product_unknown', 'Цену какого товара посмотреть?', true),
('whieda', 'compare_second_product_unknown', 'С чем сравнить Активатор клеток?', true),
('whieda', 'details_topic_unknown', 'Что раскрыть подробнее: применение, ситуации, опыт людей, механизм, исследования или материалы?', true),
('whieda', 'fallback_menu', 'Пока не смог точно определить запрос. Выберите: товар, цена/PV, применение, сравнение, фото/видео или бизнес-вопрос.', true),
('whieda', 'product_ambiguity_paste', 'Вы про зубную пасту с экстрактом полыни или Пасту Цинфэн?', true)
on conflict (client_id, clarification_key) do update set prompt_text=excluded.prompt_text, enabled=true;

-- product_comparisons
insert into advisor_structured_product_comparisons (client_id, comparison_id, title, answer_text, left_sku, right_sku, priority, active) values
('whieda', 'activator_base_vs_pro_v1', 'Активатор клеток и Активатор клеток PRO', '<b>Активатор клеток или Активатор клеток PRO?</b>  По основной задаче это один и тот же прибор для локальной домашней процедуры. PRO не «лечит сильнее»: отличия в комплектации, удобстве и настройках.  <b>Базовый Активатор</b> • простой рабочий прибор без премиальной комплектации • удобен, когда нужен сам активатор и важна практичность • упаковка зависит от варианта покупки; это не кейс для регулярных поездок  <b>Активатор PRO</b> • качественный защитный кейс для поездок и презентаций • более премиальный внешний вид и материалы • блокировка кнопок от случайного нажатия • отдельная регулировка воздуха и нагрева • режим для работы с аромамаслами, дополнительные насадки, фильтр-сетка и автопродувка  <b>Как выбрать</b> Базовый — если нужен понятный и практичный прибор. PRO — если важны кейс, поездки, презентации и больше настроек.  Насадки PRO требуют бережного обращения. Цену могу дать отдельно по актуальному прайсу.', 'M015-00', 'EU-N000031-25', 100, true)
on conflict (client_id, comparison_id) do update set title=excluded.title, answer_text=excluded.answer_text, left_sku=excluded.left_sku, right_sku=excluded.right_sku, priority=excluded.priority, active=true;

