('whieda', 'BASKET-BY-PERSONAL', 'by', 'Старт для личного использования', 'personal', '0', '1000', NULL, NULL, NULL, 'D014|D013|T015', NULL, 'Продукты для спокойного личного использования без акцента на бизнес.', 90, 'draft', 'system_seed', '2026-07-26'),
('whieda', 'BASKET-BY-DEMO', 'by', 'Старт для демонстраций', 'demo', '0', '2500', NULL, NULL, NULL, 'M015-00|D014|D013', NULL, 'Компактные продукты, которые удобно показать и дать попробовать.', 100, 'draft', 'system_seed', '2026-07-26'),
('whieda', 'BASKET-BY-GIFT', 'by', 'Старт с подарочным потенциалом', 'gift', '0', '1000', NULL, NULL, NULL, 'D014|D013|T015', NULL, 'Подходит для личного использования и как аккуратный подарок.', 90, 'draft', 'system_seed', '2026-07-26'),
