insert into advisor_promotions (client_id, promotion_id, tenant_id, title, short_text, full_text, country, city, starts_at, ends_at, timezone, promotion_type, product_ids, min_amount, min_pv, benefit_text, source_url, image_url, priority, status, owner, updated_at) values
('whieda', 'PROMO-2026-07-BY-REPEAT-60', 'by', 'Повторная покупка от 60 PV: Роза Фохоу в подарок', 'Для Беларуси: от 60 PV при повторной покупке - 1 уп. Роза Фохоу в подарок за заказ, максимум 6 уп.', 'Для Беларуси при повторной покупке от 60 PV партнер получает 1 упаковку Роза Фохоу в подарок за один заказ, максимум 6 упаковок. Акция на повторную покупку суммируется с другими акциями на повторную покупку.', 'Belarus', NULL, '2026-06-29T00:00:00', '2026-07-28T23:59:59', 'Europe/Minsk', 'gift', NULL, NULL, '60', 'Роза Фохоу в подарок', NULL, NULL, 100, 'active', 'WHIEDA official', '2026-07-26'),
('whieda', 'PROMO-2026-07-BY-REPEAT-WENTUN-SLEEP', 'by', 'Повторная покупка Вэнтуна или системы сна: 2 масла-эссенции', 'Для Беларуси: при повторной покупке Вэнтуна или системы сна 4 в 1 - 2 масла-эссенции в подарок.', 'Для Беларуси при выборе Системы для сна 4 в 1 или прибора Вэнтун в качестве повторной покупки партнер получает 2 масла-эссенции. Эта акция суммируется с другими акциями на повторную покупку.', 'Belarus', NULL, '2026-06-29T00:00:00', '2026-07-28T23:59:59', 'Europe/Minsk', 'gift', 'EU-N000014-24,EU-N000024-24', NULL, NULL, '2 масла-эссенции в подарок', NULL, NULL, 110, 'active', 'WHIEDA official', '2026-07-26'),
('whieda', 'PROMO-2026-07-UPGRADE-PREMIUM', 'by', 'Апгрейд до Premium 2000 PV: Активатор в подарок', 'При апгрейд-заказе до Premium 2000 PV - Активатор клеток без упаковки в подарок.', 'При совершении апгрейд-заказа до пакета Premium 2000 PV партнер получает 1 Активатор клеток без упаковки в подарок.', 'Belarus', NULL, '2026-06-29T00:00:00', '2026-07-28T23:59:59', 'Europe/Minsk', 'gift', 'M015-00', NULL, '2000', 'Активатор клеток без упаковки в подарок', NULL, NULL, 100, 'active', 'WHIEDA official', '2026-07-26'),
('whieda', 'PROMO-2026-07-BY-PRIMARY-STANDARD', 'by', 'Standard 500 PV: 2 упаковки комплекса Железо, Кальций, Цинк, Селен', 'Для Беларуси при регистрации Standard 500 PV - 2 упаковки комплекса Железо, Кальций, Цинк, Селен в подарок.', 'Для Беларуси при регистрации пакета Standard 500 PV партнер получает 2 упаковки Капсул Железо, Кальций, Цинк, Селен. Акции на первичные покупки между собой не суммируются.', 'Belarus', NULL, '2026-06-29T00:00:00', '2026-07-28T23:59:59', 'Europe/Minsk', 'gift', 'F007-00', NULL, '500', '2 упаковки комплекса в подарок', NULL, NULL, 120, 'active', 'WHIEDA official', '2026-07-26'),
('whieda', 'PROMO-2026-07-BY-PRIMARY-PREMIUM', 'by', 'Premium 2000 PV: Активатор и 2 масла-эссенции в подарок', 'Для Беларуси при регистрации Premium 2000 PV - Активатор без упаковки и 2 масла-эссенции в подарок.', 'Для Беларуси при регистрации пакета Premium 2000 PV партнер получает 1 Активатор клеток без упаковки и 2 масла-эссенции. Акции на первичные покупки между собой не суммируются.', 'Belarus', NULL, '2026-06-29T00:00:00', '2026-07-28T23:59:59', 'Europe/Minsk', 'gift', 'M015-00,C061-00', NULL, '2000', 'Активатор и 2 масла-эссенции в подарок', NULL, NULL, 130, 'active', 'WHIEDA official', '2026-07-26'),
('whieda', 'PROMO-2026-07-BY-GOLDEN-TRIANGLE', 'by', 'Золотой треугольник: Активатор и 2 масла-эссенции', 'Для Беларуси при регистрации трех аккаунтов - Активатор без упаковки и 2 масла-эссенции в подарок.', 'Для Беларуси при выборе опции Три аккаунта на странице регистрации основной аккаунт получает 1 Активатор клеток без упаковки и 2 масла-эссенции. Акции на первичные покупки между собой не суммируются.', 'Belarus', NULL, '2026-06-29T00:00:00', '2026-07-28T23:59:59', 'Europe/Minsk', 'gift', 'M015-00,C061-00', NULL, '1500', 'Активатор и 2 масла-эссенции в подарок', NULL, NULL, 140, 'active', 'WHIEDA official', '2026-07-26'),
('whieda', 'PROMO-2026-07-BY-REPEAT-150', 'by', 'Повторная покупка от 150 PV: специальные цены', 'Паста Цинфэн - 30 W$, омолаживающий спрей - 20 W$.', 'Для повторной покупки от 150 PV: Паста Цинфэн 30 W$ вместо 100 W$; омолаживающий спрей 20 W$ вместо 110 W$.', 'Belarus', NULL, '2026-07-19T00:00:00', '2026-07-28T23:59:59', 'Europe/Minsk', 'discount', 'F071-00,C006-00', NULL, '150', 'Спеццены 30 W$ и 20 W$', NULL, NULL, 150, 'active', 'WHIEDA local', '2026-07-26'),
('whieda', 'PROMO-2026-07-BY-STANDARD-DISCOUNT', 'by', 'Standard 500 PV: товар по специальной цене', 'При новом подключении Standard 500 PV: набор косметики 100 W$ вместо 330 W$ или Активатор клеток 100 W$ вместо 500 W$.', 'При новом подключении с пакетом Standard 500 PV доступен выбор: набор косметики за 100 W$ вместо 330 W$ или Активатор клеток за 100 W$ вместо 500 W$. Условия выбора уточнять при оформлении заказа.', 'Belarus', NULL, '2026-07-19T00:00:00', '2026-07-28T23:59:59', 'Europe/Minsk', 'discount', 'C065-00,M015-00', NULL, '500', 'Товар по специальной цене 100 W$', NULL, NULL, 160, 'active', 'WHIEDA local', '2026-07-26'),
('whieda', 'PROMO-2026-07-BY-GOLDEN-PREMIUM-BEM', 'by', 'Золотой треугольник или Premium: БЭМ 250 W$', 'При оформлении золотого треугольника 1500 PV или Premium 2000 PV: БЭМ за 250 W$ вместо 650 W$.', 'При оформлении золотого треугольника 1500 PV или пакета Premium 2000 PV доступен БЭМ за 250 W$ вместо 650 W$.', 'Belarus', NULL, '2026-07-19T00:00:00', '2026-07-28T23:59:59', 'Europe/Minsk', 'discount', 'EU-N000021-24', NULL, '1500', 'БЭМ 250 W$ вместо 650 W$', NULL, NULL, 170, 'active', 'WHIEDA local', '2026-07-26')
